html:
{
  "doc": "Corporate Compliance Register",
  "name": "Corporate Compliance Register Print",
  "doctype": "Print Format",
  "print_format_type": "Jinja",
  "standard": "No",
  "font": "Inter",
  "custom_format": 1,
  "html": "<style>
  @page { margin: 12mm 10mm 10mm 10mm; }
  * { box-sizing: border-box; }
  .container { max-width: 100%; font-family: 'Inter', -apple-system, sans-serif; color: #1a1a2e; background: #ffffff; }
  .header { border-bottom: 3px solid #0d9488; padding-bottom: 6px; margin-bottom: 10px; display: flex; justify-content: space-between; align-items: center; }
  .header h1 { font-size: 18px; font-weight: 700; color: #0d9488; margin: 0; letter-spacing: 0.3px; }
  .header .badge { background: #0d9488; color: #fff; padding: 3px 14px; border-radius: 20px; font-size: 11px; font-weight: 600; }
  .doc-info { display: flex; gap: 20px; background: #f8fafc; padding: 7px 14px; border-radius: 6px; margin-bottom: 12px; border: 1px solid #e2e8f0; font-size: 11px; flex-wrap: wrap; }
  .doc-info .item { display: flex; align-items: center; gap: 5px; }
  .doc-info .label { color: #64748b; font-weight: 500; }
  .doc-info .value { font-weight: 600; color: #0f172a; }
  .grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 6px 30px; margin-bottom: 12px; }
  .field-row { display: flex; padding: 3px 0; border-bottom: 1px solid #f1f5f9; }
  .field-row .lbl { width: 38%; font-size: 11px; color: #64748b; font-weight: 500; }
  .field-row .val { width: 62%; font-size: 12px; color: #0f172a; font-weight: 500; }
  .section-title { font-size: 13px; font-weight: 700; color: #0d9488; margin: 12px 0 6px 0; padding-bottom: 4px; border-bottom: 2px solid #e2e8f0; }
  .status-badge { display: inline-block; padding: 1px 10px; border-radius: 12px; font-size: 10px; font-weight: 600; }
  .status-Compliant { background: #dcfce7; color: #166534; }
  .status-Minor { background: #fef9c3; color: #854d0e; }
  .status-Major { background: #fee2e2; color: #991b1b; }
  .status-Non { background: #fecaca; color: #991b1b; }
  .signature-box { border-top: 1.5px solid #94a3b8; padding-top: 5px; font-size: 10.5px; color: #475569; text-align: center; width: 60%; margin-top: 14px; }
  .signature-box strong { font-size: 12px; color: #0f172a; }
  .footer { margin-top: 16px; padding-top: 8px; border-top: 2px solid #e2e8f0; display: flex; justify-content: space-between; font-size: 9px; color: #94a3b8; }
  .note-box { padding: 8px 12px; background: #f8fafc; border-radius: 6px; font-size: 10.5px; color: #475569; border-left: 3px solid #0d9488; margin-top: 8px; }
</style>
<div class="container">
  <div class="header">
    <h1>🏛️ Corporate Compliance Register</h1>
    <span class="badge">{{ doc.overall_status }}</span>
  </div>

  <div class="doc-info">
    <span class="item"><span class="label">Register #:</span> <span class="value">{{ doc.name }}</span></span>
    <span class="item"><span class="label">Title:</span> <span class="value">{{ doc.register_title }}</span></span>
    <span class="item"><span class="label">Status:</span> <span class="value"><span class="status-badge status-{{ doc.overall_status.replace(' ', '') }}">{{ doc.overall_status }}</span></span></span>
    <span class="item"><span class="label">Fiscal Year:</span> <span class="value">{{ doc.fiscal_year }}</span></span>
  </div>

  <div class="grid-2">
    <div>
      <div class="field-row"><span class="lbl">Company</span><span class="val">{{ doc.company }}</span></div>
      <div class="field-row"><span class="lbl">RC Number</span><span class="val">{{ doc.rc_number or '—' }}</span></div>
      <div class="field-row"><span class="lbl">Company Type</span><span class="val">{{ doc.company_type or '—' }}</span></div>
      <div class="field-row"><span class="lbl">Incorporation Date</span><span class="val">{{ frappe.format_date(doc.date_of_incorporation) or '—' }}</span></div>
    </div>
    <div>
      <div class="field-row"><span class="lbl">Company Secretary</span><span class="val">{{ doc.company_secretary or '—' }}</span></div>
      <div class="field-row"><span class="lbl">Last AGM</span><span class="val">{{ frappe.format_date(doc.last_agm_date) or '—' }}</span></div>
      <div class="field-row"><span class="lbl">Next AGM Due</span><span class="val">{{ frappe.format_date(doc.next_agm_due_date) or '—' }}</span></div>
      <div class="field-row"><span class="lbl">AGM Held On Time</span><span class="val">{% if doc.agm_held_on_time %}✅ Yes{% else %}⬜ No{% endif %}</span></div>
    </div>
  </div>

  <div class="section-title">📋 CAC Annual Return</div>
  <div class="grid-2">
    <div>
      <div class="field-row"><span class="lbl">Due Date</span><span class="val">{{ frappe.format_date(doc.annual_return_due_date) }}</span></div>
      <div class="field-row"><span class="lbl">Filed Date</span><span class="val">{{ frappe.format_date(doc.annual_return_filed_date) or '—' }}</span></div>
      <div class="field-row"><span class="lbl">Status</span><span class="val">{{ doc.annual_return_status }}</span></div>
    </div>
    <div>
      <div class="field-row"><span class="lbl">Receipt No</span><span class="val">{{ doc.annual_return_receipt or '—' }}</span></div>
      <div class="field-row"><span class="lbl">Penalty</span><span class="val">₦{{ frappe.format_currency(doc.annual_return_penalty) or '—' }}</span></div>
      <div class="field-row"><span class="lbl">CLL Entry</span><span class="val">{{ doc.cac_compliance_liability or '—' }}</span></div>
    </div>
  </div>

  <div class="section-title">✅ Governance Checks</div>
  <div class="grid-2">
    <div>
      <div class="field-row"><span class="lbl">Director Changes Notified</span><span class="val">{% if doc.director_changes_notified %}✅ Yes{% else %}⬜ No{% endif %}</span></div>
      <div class="field-row"><span class="lbl">Shareholder Changes Notified</span><span class="val">{% if doc.shareholder_changes_notified %}✅ Yes{% else %}⬜ No{% endif %}</span></div>
    </div>
    <div>
      <div class="field-row"><span class="lbl">Registered Address Current</span><span class="val">{% if doc.registered_address_current %}✅ Yes{% else %}⬜ No{% endif %}</span></div>
      <div class="field-row"><span class="lbl">Statutory Registers Current</span><span class="val">{% if doc.statutory_registers_current %}✅ Yes{% else %}⬜ No{% endif %}</span></div>
    </div>
  </div>

  {% if doc.notes %}
  <div class="note-box"><strong>📝 Notes:</strong> {{ doc.notes }}</div>
  {% endif %}

  <div>
    <div class="signature-box">Company Secretary<br><strong>{{ doc.company_secretary or '________________________' }}</strong></div>
  </div>

  <div class="footer">
    <span>Generated: {{ frappe.utils.nowdate() }}</span>
    <span>Document: {{ doc.name }}</span>
    <span>🏛️ Corporate Compliance</span>
  </div>
</div>"
}
